== types {"schemaId": "opensip.relation.types.v1", "selector": "#/$defs/TypesPayloadV1", "universeRule": "same-only", "subjectKind": "symbol", "anchorLaw": {"class": "source-text", "minimum": 1, "rule": "Every span this fact was read from; at least one, because an unanchored code fact names no file that could have been read."}, "ladder": ["annotated", "checked"], "rungs": {"annotated": {"required": [], "forbidden": ["checkedType"]}, "checked": {"required": ["checkedType"], "forbidden": []}}}
== unresolved-edge {"schemaId": "opensip.relation.unresolved-edge.v1", "selector": "#/$defs/UnresolvedEdgePayloadV1", "universeRule": "same-only", "subjectKind": "symbol", "anchorLaw": {"class": "source-text", "minimum": 1, "rule": "Every span this fact was read from; at least one, because an unanchored code fact names no file that could have been read."}, "ladder": ["observed"], "rungs": {"observed": {"required": [], "forbidden": []}}}
