===== native.semantic-universe.typescript.v2
{
 "document": "native/native-evidence.schemas.v2.json",
 "selector": "#/$defs/TypeScriptUniverseV2ResolvedInputs",
 "contextField": [
  "nativeContextId"
 ],
 "contextForm": "sha256-text",
 "language": "typescript",
 "binding": {
  "contract": "native-evidence",
  "section": "11",
  "entryPoint": "bind_typescript_universe",
  "arguments": [
   "universe",
   "admission",
   "context",
   "retained",
   "snapshotInventory"
  ]
 },
 "contextDomain": "native.context.typescript.v2",
 "nestedIdentities": [],
 "nestedRecords": [
  {
   "path": [
    "tsconfigGraphHash"
   ],
   "retainedAs": "configGraph",
   "form": "canonical-record",
   "document": "native/native-evidence.schemas.v2.json",
   "selector": "#/$defs/TypeScriptConfigGraphV1"
  }
 ],
 "languageVersionBinding": {
  "record": "#/$defs/body-language-version",
  "encoding": "raw-32-byte-sha256-of-canonical-record",
  "retention": "derived",
  "fields": {
   "compilerName": {
    "source": "native-context",
    "path": [
     "toolchain",
     "compilerName"
    ]
   },
   "compilerVersion": {
    "source": "native-context",
    "path": [
     "toolchain",
     "compilerVersion"
    ]
   },
   "compilerBuild": {
    "source": "native-context",
    "path": [
     "toolchain",
     "compilerPackageDigest"
    ]
   }
  },
  "dialect": {
   "key": "sourceVariant",
   "source": "anchor-path-suffix",
   "form": "closed-suffix-table",
   "table": {
    ".d.ts": "ts-declaration",
    ".ts": "ts",
    ".tsx": "tsx",
    ".mts": "mts",
    ".cts": "cts",
    ".js": "js",
    ".jsx": "jsx",
    ".mjs": "mjs",
    ".cjs": "cjs"
   },
   "onUnknown": "BODY_LANGUAGE_SOURCE_VARIANT_UNKNOWN",
   "selectionLaw": "TypeScript has no per-crate dialect map; its per-body axis is the SOURCE VARIANT its own file suffix denotes, which decides how the body is scanned and parsed. Longest matching suffix wins, so .d.ts is never read as .ts. An unlisted suffix REFUSES rather than being folded into a neighbouring variant, so a normal variant is never silently mis-assigned and a new one must be registered deliberately. Distinct suffixes stay distinct even where a parser would treat two alike: this can fail to equate two bodies that are in fact equivalent, and can never equate two the language reads differently. Collapsing variants is a claim about a parser and belongs to the level specification. Only the variant token enters the record; the path does not."
  },
  "excluded": {
   "libSelection": "standard library selection resolves types; it does not interpret a body span",
   "typescriptStdlibMerkleRoot": "same, and it is a retained artifact digest not a language identity",
   "standardLibraryComponentDigests": "same",
   "languageMode": "configuration and program assembly, not the language",
   "synthesizerVersion": "the option synthesizer, not the compiler that reads the body",
   "packageModuleType": "module resolution semantics, not body interpretation",
   "anchorPath": "the path establishes the variant and then does not enter the record; two identical bodies at different paths in one variant have one identity"
  },
  "bodyLanguages": [
   "typescript",
   "javascript"
  ],
  "bodyLanguageByVariant": {
   "ts": "typescript",
   "tsx": "typescript",
   "ts-declaration": "typescript",
   "mts": "typescript",
   "cts": "typescript",
   "js": "javascript",
   "jsx": "javascript",
   "mjs": "javascript",
   "cjs": "javascript"
  },
  "bodyLanguageLaw": "The body languageId is DERIVED from the selected source variant, not from the provider universe. The universe language is the engine that reads the body; a .js body read by the TypeScript engine is a javascript body and must carry that identifier, exactly as native section 6.3 requires. The frame languageId and the record languageId are both taken from this one selector over the same anchor, so they cannot disagree. No JavaScript body is rewritten as TypeScript, and the cross-tsjs candidate projection of section 6.4 is untouched."
 }
}
