  "entryPoint": "bind_rust_universe",
  "arguments": [
   "universe",
   "admission",
   "context",
   "retained",
   "snapshotInventory"
  ]
 },
 "nestedIdentities": [
  {
   "path": [
    "dependencySourceSetId"
   ],
   "form": "sha256-text",
   "domainSet": "native-nested",
   "retainedAs": "dependencySourceSet"
  },
  {
