   "domainSet": "native-nested"
  },
  {
   "path": [
    "sourceUnitOwnershipId"
   ],
   "form": "sha256-text",
   "domainSet": "native-nested",
   "nullable": true,
   "retainedAs": "sourceUnitOwnership"
  }
 ],
 "preparedResolutionGrantOperations": {
  "host-prepared": "prepare-code",
  "imported-inert": "read-import",
  "none": null
 },
 "languageVersionBinding": {
  "record": "#/$defs/body-language-version",
  "encoding": "raw-32-byte-sha256-of-canonical-record",
  "retention": "derived",
  "fields": {
   "compilerName": {
    "const": "rustc"
   },
   "compilerVersion": {
    "source": "native-context",
    "path": [
     "toolchain",
     "rustcVersion"
    ]
   },
   "compilerBuild": {
    "source": "native-context",
    "path": [
     "toolchain",
     "rustCommitHash"
    ]
   }
  },
  "dialect": {
   "key": "edition",
   "source": "universe",
   "path": [
    "edition"
   ],
   "form": "selected-compilation-target-edition",
   "ownership": {
    "source": "retained",
    "retainedAs": "sourceUnitOwnership",
    "pathField": "path",
    "unitField": "unitId",
    "unitsField": "units",
    "crateField": "crateName",
    "targetEditionField": "targetEdition",
    "selectionField": "selectedUnitIds",
    "enumerationField": "enumeration"
   },
   "onEmpty": "BODY_LANGUAGE_DIALECT_ABSENT",
   "onAmbiguous": "BODY_LANGUAGE_DIALECT_AMBIGUOUS",
   "onOwnerNotCompiled": "BODY_LANGUAGE_OWNER_NOT_COMPILED",
   "onOwnerUnenumerated": "BODY_LANGUAGE_OWNER_UNENUMERATED",
   "onOwnerAmbiguous": "BODY_LANGUAGE_OWNER_AMBIGUOUS",
   "onOwnershipMissing": "BODY_LANGUAGE_OWNERSHIP_REQUIRED",
   "selectionLaw": "The dialect is the EFFECTIVE edition of the SELECTED compilation target that owns this body path: the unit targetEdition when it states one, otherwise the universe edition map entry for its crateName. There is NO fast path - Cargo lets a target override its package default, so package defaults that all agree still do not determine a body dialect - and a clones fact over any Rust universe therefore requires the committed SourceUnitOwnershipV1 whatever the package map looks like. The order of decision is fixed and each step has its own cause: (1) no committed ownership refuses; (2) enumeration partial refuses BEFORE any row is looked at, so incomplete discovery can never act as an implicit edition selection by hiding a conflicting owner; (3) rows are those whose path EQUALS the enclosing fact anchor path - never a prefix, never a nearest directory, never a first match - and no row at all refuses as not-compiled; (4) rows are then restricted to selectedUnitIds, and a path compiled only by unselected targets refuses as not-selected rather than borrowing an out-of-scope edition; (5) SELECTED owners whose effective editions AGREE are admissible, which is the ordinary shared-file and lib-plus-test-target case; (6) selected owners that DISAGREE are an ambiguous unselected request and refuse. Because selectedUnitIds is committed inside the record whose H identity the universe names, each selection is a DIFFERENT sourceUniverse: one physical path compiled at two editions is validly analysed under each, one selection at a time. Selection establishes the JOIN only - no path, crate name, unit id or selection enters the body-language-version record.",
   "alwaysRequired": true,
   "onOwnerNotSelected": "BODY_LANGUAGE_OWNER_NOT_SELECTED",
   "scopeVersusEnumeration": "SELECTED SCOPE and INCOMPLETE ENUMERATION are different claims and neither substitutes for the other. A selection says these targets ARE the analysis, so an owner outside them is deliberately out of scope and its edition does not bear on this body; the selection is committed in the identity, so it is visible to every consumer and changes the universe. Incomplete enumeration says the producer did not finish, so an owner INSIDE the selected scope may exist that is not listed and could contradict a listed one; that is a gap in knowledge, it is not visible as a selection, and it therefore admits no body dialect at all. Silently omitting a conflicting owner from the units table is not a selection either: an omission leaves no trace, whereas a selection is part of the universe identity. Partial evidence stays useful under the existing law rather than voiding a Run: the clones scope simply mints no body identity, its Coverage carries the incompleteness, the predicate is indeterminate and the seal is indeterminate."
  },
  "excluded": {
   "targetTriple": "operational platform",
   "hostTriple": "operational platform",
   "sysrootDigest": "retained artifact of the resolution environment, not a language identity",
   "rustcDevLlvmDigest": "code generation backend; it does not interpret a body span",
   "standardLibraryComponentDigests": "resolution inputs, not body interpretation",
   "cargoVersion": "build and dependency tool; it does not read the body",
   "resolverVersion": "dependency resolution, not language",
   "crateRootPaths": "paths, and a body identity must not vary with where a crate sits",
   "editionMapKeys": "crate NAMES; one body identity must not depend on unrelated crates"
  },
  "dialectRepresentableForm": "An ordinary mixed-edition workspace has a representable valid form: each source path is owned by units of one edition, so every body gets its own dialect and bodies of BOTH editions close in the same universe. Only a path genuinely compiled under two different editions refuses.",
  "bodyLanguages": [
   "rust"
  ],
  "bodyLanguage": "rust"
 }
}
===== native.semantic-universe.syntax.v2
{
 "document": "native/native-evidence.schemas.v2.json",
 "selector": "#/$defs/SyntaxUniverseV2ResolvedInputs",
 "contextField": [
  "nativeContextId"
 ],
 "contextForm": "sha256-text",
 "language": "syntax",
 "binding": {
  "contract": "native-evidence",
  "section": "1.2",
  "entryPoint": "bind_syntax_universe",
  "arguments": [
   "universe",
   "admission",
   "context",
   "retained",
   "snapshotInventory"
  ]
 },
 "contextDomain": "native.context.syntax.v2",
 "nestedIdentities": [],
 "nestedRecords": [],
 "note": "The universe of the syntax-only mode. `semantic universe` names the thing that DETERMINES a fact, and for a grammar-only analysis that is the selected bundled-grammar set, not a compiler semantic model. It exists because the capability matrix advertises declares/literal/control-flow at `syntactic` and clones at `normalized-body-hash` for syntax-only, and because file/package/vcs-change inventory facts must be representable in a repository that contains no TypeScript and no Rust unit at all: fact2 and subject-scope both REQUIRE a universe h-identity from this closed domain set, so with only the two compiler universes registered those advertised cells could mint no fact and no scope. Making the universe fields nullable was rejected: it would delete the invariant that every fact states what produced it, and would leave `which grammar read this body` unanswerable for exactly the facts that depend on it. Semantic capability is NOT widened by this domain - a syntax-only universe can carry only the syntactic and inventory rungs and the clones rung; imports/references/calls/types/reachability remain language-tier-unsupported, and a universal negative still requires its own complete Coverage.",
 "languageVersionBinding": {
  "record": "#/$defs/body-language-version",
  "encoding": "raw-32-byte-sha256-of-canonical-record",
  "retention": "derived",
  "fields": {
   "compilerName": {
    "source": "native-context",
    "path": [
     "grammarBundle",
     "parserName"
    ]
   },
   "compilerVersion": {
    "source": "native-context",
    "path": [
     "grammarBundle",
     "parserVersion"
    ]
   },
   "compilerBuild": {
    "source": "native-context",
    "path": [
     "grammarBundle",
     "bundleDigest"
    ]
   }
  },
  "componentLaw": "body-language-version names THE COMPONENT THAT INTERPRETS THE BODY SPAN - explicitly not the build tool and not the resolver. Under syntax-only that component is the bundled grammar's parser, so the three fields are bound to the retained, closure-joined grammar bundle rather than to a toolchain. No static constant and no fabricated compiler identity is used: parserVersion is joined by admission to the grammar closure's manifest semanticVersion exactly as the compiler versions are, and bundleDigest is the exact retained bundle identity. A body read by the grammar therefore has a DIFFERENT languageVersion from the same bytes read by tsc or rustc, so their clone identities differ. That is required, not incidental: equating a grammar parse with a compiler parse would assert an interpretation that was never performed.",
  "dialect": {
   "key": "grammarVariant",
   "source": "anchor-path-suffix",
   "form": "closed-suffix-table",
   "table": {
    ".rs": "rs",
    ".d.ts": "ts-declaration",
    ".ts": "ts",
    ".tsx": "tsx",
    ".mts": "mts",
    ".cts": "cts",
    ".js": "js",
    ".jsx": "jsx",
    ".mjs": "mjs",
    ".cjs": "cjs"
   },
   "onUnknown": "BODY_LANGUAGE_GRAMMAR_VARIANT_UNKNOWN",
   "selectionLaw": "A syntax-only analysis has no compilation unit, so it has no edition to select and no program to join; its only per-body axis is the variant the bundled grammar selects from the body's own suffix. Longest matching suffix wins, so .d.ts is never read as .ts. A suffix with no bundled grammar REFUSES rather than being folded into a neighbouring variant - which is the same conservative rule the compiler universes use, and it is what keeps `unsupported-file / no-bundled-grammar` an honest classification rather than a silent reinterpretation. Crucially there is NO edition branch here: a .rs body read without Cargo has no admitted ownership, and inventing one would be exactly the fabricated compiler semantics this mode exists to avoid."
  },
  "excluded": {
   "languageMode": "configuration and unit assembly, not the language",
   "anchorPath": "the path establishes the variant and then does not enter the record",
   "normalizerSpecificationDigest": "the clone normalisation level specification is already a separate framed component; it is not the interpreter of the span",
   "grammarSelection": "which grammars this analysis selected is committed in the universe identity; it is not a property of one body"
  },
  "bodyLanguages": [
   "typescript",
   "javascript",
   "rust"
  ],
  "bodyLanguageByVariant": {
   "rs": "rust",
   "ts": "typescript",
   "tsx": "typescript",
   "ts-declaration": "typescript",
   "mts": "typescript",
   "cts": "typescript",
   "js": "javascript",
   "jsx": "javascript",
   "mjs": "javascript",
   "cjs": "javascript"
  },
  "bodyLanguageLaw": "The body language is the language of the BODY, from the same suffix selector, and is closed to the body-language-version languageId enum. The bundled grammar set and that enum are held equal by an explicit drift check, so a newly bundled grammar cannot start producing bodies of an unregistered language and the advertised `any file whose extension maps to a bundled grammar` cannot silently outrun what the identity record can express."
 }
}

