===== body-language-version
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "languageId",
  "compilerName",
  "compilerVersion",
  "compilerBuild",
  "dialect"
 ],
 "description": "The closed record whose raw SHA-256 is the languageVersion component of a FACT-IDENTITY body frame. Retention is DERIVED: no field of it is a free input, every field is copied from a named path in a record this Run already retains and the owning contract already admitted, and Run closure recomputes it rather than accepting it. Two conforming implementations build identical bytes from the same committed Run, which is what the inherited obligation \"canonical identity bytes supplied by ResolvedInputs/PlanId, not a human display string\" asks for. It is hashed, not embedded, because the inherited frame gives each component a u8 length and a component built by embedding per-crate data is not representable for valid inputs.",
 "properties": {
  "schemaVersion": {
   "const": 1
  },
  "languageId": {
   "type": "string",
   "enum": [
    "typescript",
    "javascript",
    "rust"
   ],
   "description": "The language of the BODY, which is not always the language of the provider. Native section 6.3 puts languageId in the normalized-body preimage and closes it to {typescript, javascript, rust} so that a TypeScript body never groups with a JavaScript one even with identical bytes. One TypeScript engine universe produces bodies of BOTH: the engine is the provider, the source variant decides the body language, and section 6.4 keeps cross-TS/JS matching a separate candidate-only projection rather than a shared identity."
  },
  "compilerName": {
   "type": "string",
   "minLength": 1,
   "maxLength": 256,
   "description": "The component that INTERPRETS the body span. Not the build tool and not the resolver."
  },
  "compilerVersion": {
   "type": "string",
   "minLength": 1,
   "maxLength": 256,
   "description": "The release identity of that component, taken from the admitted native context. admit_native_context already refuses native.native-context-compiler-version-not-from-manifest unless it equals the admitted tool closure semanticVersion, for both languages, so this is joined to a retained closure manifest and is not a copied display string."
  },
  "compilerBuild": {
   "type": "string",
   "minLength": 1,
   "maxLength": 512,
   "description": "The exact build of that component: rustCommitHash for rust, compilerPackageDigest for typescript. Not a 64-hex field of this bundle and deliberately not annotated as one: it is an owner-admitted identity carried inside a derived record, joined by equality to the retained context and never re-hashed here. Its width differs by language by construction."
  },
  "dialect": {
   "oneOf": [
    {
     "type": "object",
     "additionalProperties": false,
     "required": [
      "edition"
     ],
     "properties": {
      "edition": {
       "type": "integer",
       "enum": [
        2015,
        2018,
        2021,
        2024
       ]
      }
     }
    },
    {
     "type": "object",
     "additionalProperties": false,
     "required": [
      "sourceVariant"
     ],
     "properties": {
      "sourceVariant": {
       "type": "string",
       "enum": [
        "ts",
        "tsx",
        "ts-declaration",
        "mts",
        "cts",
        "js",
        "jsx",
        "mjs",
        "cjs"
       ]
      }
     }
    },
    {
     "type": "object",
     "additionalProperties": false,
     "required": [
      "grammarVariant"
     ],
     "description": "The dialect axis of a GRAMMAR-ONLY interpretation; used only by the syntax-only universe. A syntax-only analysis has no compilation unit, so it has no edition to select and no tsconfig program to join. Claiming an edition for a .rs body read without Cargo would fabricate compiler semantics, and reusing sourceVariant would let a grammar-parsed body carry the identical dialect token as a compiler-parsed one. The token is the variant the bundled grammar selects from the body's own suffix. Because this is a DIFFERENT branch, a syntax-only body identity can never collide with a compiler-derived identity over the same bytes - which is the intended distinction, not a defect: a grammar parse and a compiler parse are different interpretations of the span and equating them would be a false clone claim.",
     "properties": {
      "grammarVariant": {
       "type": "string",
       "enum": [
        "rs",
        "ts",
        "tsx",
        "ts-declaration",
        "mts",
        "cts",
        "js",
        "jsx",
        "mjs",
        "cjs"
       ]
      }
     }
    }
   ],
   "description": "The SELECTED source-language dialect of the body being identified: the edition of its owning compilation unit, the source variant its own suffix denotes, or - for a grammar-only interpretation - the grammar variant that suffix selects. Never a whole map and never null - a language with no declared dialect axis would be an unexamined default, and there is none. Including a map would make one body identity depend on unrelated crates and would not be representable inside the inherited u8 component length."
  }
 }
}
